TEXT_SUFFIXES = {".cppm", ".cpp", ".c", ".h", ".hpp", ".inl", ".test", ".lua", ".cmake", ".py", ".slang", ".slangh", ".txt", ".rc", ".dsp", ".dsw", ".ini", ".cfg", ".def", ".mak", ".htm", ".html", ".xml"}
TOKEN = re.compile(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|//[^\n]*|/\*.*?\*/', re.S)

def fingerprint(path):
    data = path.read_bytes()
    if path.suffix.lower() in TEXT_SUFFIXES and b"\0" not in data:
        data = data.replace(b"\r\n", b"\n")
    return hashlib.sha256(data).hexdigest()

def uncomment(text):
    return TOKEN.sub(lambda m: "\n" * m[0].count("\n") if m[0].startswith("/") else m[0], text)

def row(kind, feature, source, placement, notes="", milestone="parity"):
    return dict(zip(COLUMNS, [f"{kind}:{feature}", kind, feature, source, placement, "", "", "not_started", "", milestone, notes]))

def placement(path):
    domain = path.split("/")[1].lower() if path.startswith("Code/") else "content"
    return {
        "ww3d2": "engine/graphics", "wwmath": "engine/core/math", "wwphys": "engine/gameplay/common/physics",
        "wwui": "engine/gui/w3d", "wwaudio": "engine/audio", "wwlib": "engine/filesystem",
        "wwnet": "engine/net", "wwbitpack": "engine/core/serialization", "wwsaveload": "engine/core/serialization",
        "wwtranslatedb": "engine/localization", "scripts": "games/renegade/content/scripts",
        "combat": "games/renegade/gameplay", "commando": "games/renegade/session",
    }.get(domain, "games/renegade/migration")

def script_items(path, text):
    clean = uncomment(text)
    result = []
    for match in re.finditer(r'\bDECLARE_SCRIPT\s*\(\s*(\w+)\s*,\s*("(?:\\.|[^"\\])*")\s*\)', clean):
        name = match[1]
        line = clean[:match.start()].count("\n") + 1
        source = f"{path}:{line}"
        result.append(row("script", name, source, "games/renegade/content/scripts", "Parameters: " + match[2]))
        begin = clean.find("{", match.end())
        if begin < 0:
            raise ValueError(f"Cannot locate body of {name}")
        # Mask strings before balancing braces so strings cannot end a class.
        masked = TOKEN.sub(lambda m: " " * len(m[0]), clean)
        depth = 1
        end = begin + 1
        while end < len(masked) and depth:
            depth += (masked[end] == "{") - (masked[end] == "}")
            end += 1
        body = clean[begin:end]
        for event in sorted(EVENTS):
            found = re.search(r'\b' + event + r'\s*\([^;{}]*\)\s*(?:const\s*)?(?:override\s*)?\{', body)
            if found:
                callback_line = clean[:begin + found.start()].count("\n") + 1
                result.append(row("callback", name + "." + event, f"{path}:{callback_line}", "games/renegade/content/scripts"))
    return result

def retail_items(install):
    result = []
    data = install / "Data"
    for file in sorted(data.rglob("*")):
        if not file.is_file(): continue
        name = file.relative_to(install).as_posix()
        result.append(row("retail", name, name, "games/renegade/content", f"Physical file; bytes={file.stat().st_size}"))
        with file.open("rb") as stream:
            header = stream.read(12)
            if len(header) != 12 or header[:4] != b"MIX1": continue
            _, index, names = struct.unpack("<4sII", header)
            stream.seek(index)
            count = struct.unpack("<I", stream.read(4))[0]
            records = dict((crc, (offset, length)) for crc, offset, length in (struct.unpack("<III", stream.read(12)) for _ in range(count)))
            stream.seek(names)
            if struct.unpack("<I", stream.read(4))[0] != count: raise ValueError(f"MIX name count mismatch: {name}")
            for _ in range(count):
                length = stream.read(1)[0]
                raw = stream.read(length)
                if not raw.endswith(b"\0"): raise ValueError(f"MIX unterminated name: {name}")
                embedded = raw[:-1].decode("latin-1")
                key = zlib.crc32(raw[:-1].upper())
                offset, size = records[key]
                result.append(row("retail", name + "::" + embedded.lower(), name + "::" + embedded,
                    "games/renegade/content", f"MIX1 entry; crc={key:08x}; offset={offset}; bytes={size}"))
    return result

