def behavior_items():
    return [row("behavior", *item) for item in BEHAVIORS]

def load_rows(directory):
    rows = []
    for filename in FILES.values():
        path = directory / filename
        if path.exists():
            with path.open(newline="", encoding="utf-8") as stream:
                reader = csv.DictReader(stream)
                if reader.fieldnames != COLUMNS: raise ValueError(f"Invalid columns: {path}")
                rows.extend(reader)
    return rows

def validate(rows, inventory, root):
    expected = {item["id"] for item in inventory["items"]} | {item["id"] for item in behavior_items()}
    actual = [item["id"] for item in rows]
    errors = []
    if len(actual) != len(set(actual)): errors.append("duplicate ledger ids")
    missing, extra = expected - set(actual), set(actual) - expected
    if missing: errors.append(f"missing {len(missing)} inventory rows: {sorted(missing)[:3]}")
    if extra: errors.append(f"unexpected {len(extra)} rows: {sorted(extra)[:3]} (add behavior to BEHAVIORS first)")
    immutable = {item["id"]: item for item in inventory["items"]}
    source_paths = set(inventory.get("source_sha256", {}))
    receipts = {}
    for item in rows:
        original = immutable.get(item["id"])
        if original and any(item[key] != original[key] for key in ("kind", "feature", "legacy_source")):
            errors.append(f"{item['id']}: inventory provenance changed")
        if source_paths and item["kind"] == "behavior":
            path = item["legacy_source"].split(":")[0]
            if path not in source_paths and not any(file.startswith(path + "/") for file in source_paths):
                errors.append(f"{item['id']}: behavior source missing from pinned inventory")
        if item["status"] not in STATUSES: errors.append(f"{item['id']}: invalid status")
        if not item["legacy_source"] or not re.fullmatch(r"(?:engine|games/renegade)(?:/[a-z0-9_/-]+)?", item["placement"]):
            errors.append(f"{item['id']}: invalid source/placement")
        if item["status"] in {"ported", "verified"}:
            for field in ("target_paths", "tests"):
                if not item[field]: errors.append(f"{item['id']}: {field} required for parity claim")
                for path in filter(None, item[field].split(";")):
                    real = (root / path).resolve()
                    if not real.is_relative_to(root.resolve()) or not real.is_file(): errors.append(f"{item['id']}: missing or unsafe {field}: {path}")
            if item["status"] == "verified":
                if not item["verification"]: errors.append(f"{item['id']}: verification receipt required")
                elif not (root / item["verification"]).is_file(): errors.append(f"{item['id']}: missing verification receipt")
                else:
                    path = (root / item["verification"]).resolve()
                    if not path.is_relative_to(root.resolve()):
                        errors.append(f"{item['id']}: unsafe receipt path")
                        continue
                    if path not in receipts:
                        receipt = json.loads(path.read_text(encoding="utf-8"))
                        receipts[path] = receipt
                        if receipt.get("revision") != REVISION or not receipt.get("passed_tests"):
                            errors.append("invalid validation receipt")
                        for file, digest in receipt.get("file_sha256", {}).items():
                            real = (root / file).resolve()
                            if not real.is_relative_to(root.resolve()) or not real.is_file() or fingerprint(real) != digest:
                                errors.append(f"stale validation receipt: {file}; rebuild, retest and record")
                    receipt = receipts[path]
                    if item["id"] not in receipt.get("claims", []): errors.append(f"{item['id']}: receipt does not verify this claim")
                    for file in (item["target_paths"] + ";" + item["tests"]).split(";"):
                        if file and file not in receipt.get("file_sha256", {}): errors.append(f"{item['id']}: unrecorded evidence file: {file}")
        if item["status"] == "not_applicable" and not item["notes"]: errors.append(f"{item['id']}: exclusion needs rationale")
    return errors

def write_rows(rows):
    for kind, filename in FILES.items():
        with (MIGRATION / filename).open("w", newline="", encoding="utf-8") as stream:
            writer = csv.DictWriter(stream, COLUMNS, lineterminator="\n"); writer.writeheader()
            writer.writerows(sorted((item for item in rows if item["kind"] == kind), key=lambda item: item["id"]))

def record(results):
    tree = ET.parse(results)
    cases = list(tree.getroot().iter("testcase"))
    if not cases or any(case.get("status") != "run" or case.find("failure") is not None or case.find("error") is not None or case.find("skipped") is not None for case in cases):
        raise ValueError("record requires a fully passing CTest JUnit result")
    passed = {case.get("name") for case in cases}
    if any(required not in passed for required, _, _ in CLAIMS.values()): raise ValueError("result omits a required parity test")
    receipt = {"revision": REVISION, "platform": sys.platform, "tested_at": tree.getroot().get("timestamp"),
        "passed_tests": sorted(passed), "claims": sorted(CLAIMS), "file_sha256": {}, "hash_policy": "SHA256; text CRLF normalized to LF"}
    # Hash the shared module sources too: edits to dependencies invalidate proof.
    for base in (ROOT / "engine", ROOT / "games/renegade"):
        for file in sorted(base.rglob("*")):
            if file.is_file() and (file.suffix in {".cppm", ".cpp", ".test", ".lua", ".cmake", ".py", ".slang", ".slangh"} or file.name == "CMakeLists.txt"):
                receipt["file_sha256"][file.relative_to(ROOT).as_posix()] = fingerprint(file)
    receipt["toolchain"] = json.loads((ROOT / "engine/cmake/toolchain/lock.json").read_text())["versions"]
    (ROOT / RECEIPT).write_text(json.dumps(receipt, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    rows = load_rows(MIGRATION)
    for item in rows:
        if item["id"] in CLAIMS:
            _, item["target_paths"], item["tests"] = CLAIMS[item["id"]]
            item["status"], item["verification"] = "verified", RECEIPT
        if item["id"] in {"behavior:net.authority", "behavior:missions.lua", "behavior:gui.hud", "behavior:ecs.composition"}:
            item["status"] = "in_progress"
    write_rows(rows)
    return rows

def sync(source, install):
    revision = subprocess.check_output(["git", "-C", str(source), "rev-parse", "HEAD"], text=True).strip()
    if revision != REVISION: raise ValueError(f"Expected pinned EA revision {REVISION}, found {revision}")
    items, hashes = [], {}
    for directory in ("Code", "Run"):
        for path in sorted((source / directory).rglob("*")):
            if not path.is_file(): continue
            relative = path.relative_to(source).as_posix()
            content = path.read_bytes()
            hashes[relative] = fingerprint(path)
            items.append(row("source", relative, relative, placement(relative), "Source inventory only; split behavior before claiming whole-file parity"))
            if relative.startswith("Code/Scripts/") and path.suffix.lower() in {".cpp", ".h"}:
                items.extend(script_items(relative, content.decode("latin-1")))
    items.extend(retail_items(install))
    # Some legacy build variants register the same script name twice.
    # Preserve each registration rather than silently discard the second.
    duplicates = Counter(item["id"] for item in items)
    for item in items:
        if duplicates[item["id"]] > 1: item["id"] += "@" + item["legacy_source"]
    inventory = {"repository": "https://github.com/electronicarts/CnC_Renegade", "revision": revision, "source_sha256": hashes,
        "items": [{key: item[key] for key in ("id", "kind", "feature", "legacy_source")} for item in items]}
    previous = {item["id"]: item for item in load_rows(MIGRATION)}
    rows = []
    for item in items + behavior_items():
        edited = previous.get(item["id"], {})
        for field in ("target_paths", "tests", "status", "verification", "milestone"):
            if field in edited: item[field] = edited[field]
        if edited.get("notes"): item["notes"] = edited["notes"]
        rows.append(item)
    (MIGRATION / "inventory.json").write_text(json.dumps(inventory, sort_keys=True, indent=2) + "\n", encoding="utf-8")
    write_rows(rows)
    return rows

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=("sync", "check", "summary", "record"))
    parser.add_argument("--source", type=Path); parser.add_argument("--install", type=Path)
    parser.add_argument("--results", type=Path)
    args = parser.parse_args()
    if args.command == "sync":
        if not args.source or not args.install: parser.error("sync requires --source and --install")
        rows = sync(args.source, args.install)
    elif args.command == "record":
        if not args.results: parser.error("record requires --results <CTest JUnit XML>")
        rows = record(args.results)
    else:
        inventory = json.loads((MIGRATION / "inventory.json").read_text(encoding="utf-8"))
        if inventory["revision"] != REVISION: raise ValueError("inventory revision mismatch")
        rows = load_rows(MIGRATION)
        errors = validate(rows, inventory, ROOT)
        if args.source:
            for path, digest in inventory["source_sha256"].items():
                file = args.source / path
                if not file.is_file() or fingerprint(file) != digest: errors.append(f"source hash mismatch: {path}")
        if errors: raise ValueError("\n".join(errors))
    print(f"Ledger: {len(rows)} rows; " + ", ".join(f"{kind}={count}" for kind, count in sorted(Counter(item['kind'] for item in rows).items())))
    print("Statuses: " + ", ".join(f"{status}={count}" for status, count in sorted(Counter(item['status'] for item in rows).items())))

if __name__ == "__main__":
    try: main()
    except (ValueError, OSError, KeyError) as error:
        print(f"ledger: {error}", file=sys.stderr); sys.exit(1)
